package solution

func Average(nums []int) float64 {
	if len(nums) == 0 {        // guard empty input
		return 0               // the zero value is a sensible result
	}
	sum := 0                   // int zero value
	for _, n := range nums {
		sum += n
	}
	// explicit conversions: no implicit int->float64
	return float64(sum) / float64(len(nums))
}

