package solution

import "testing"

func TestAverage(t *testing.T) {
	cases := []struct {
		in   []int
		want float64
	}{
		{[]int{2, 4, 6}, 4},
		{[]int{}, 0},
		{[]int{5}, 5},
	}
	for _, c := range cases {
		if got := Average(c.in); got != c.want {
			t.Errorf("Average(%v)=%g want %g", c.in, got, c.want)
		}
	}
}

